import keras


def build_lattice_3d() -> keras.Model:
    """Generated by NTB from lattice-3d. Do not edit by hand."""
    x = keras.Input(batch_shape=(None, 64), dtype="float32", name="x")
    col0_0_mix = keras.layers.Add()([x])
    col0_0_fc = keras.layers.Dense(units=64, use_bias=True)(col0_0_mix)
    col0_0_norm = keras.layers.LayerNormalization(epsilon=1e-05, scale=True)(col0_0_fc)
    col0_0_act = keras.activations.gelu(col0_0_norm, approximate=False)
    col1_0_mix = keras.layers.Add()([col0_0_act])
    col2_0_mix = keras.layers.Add()([col0_0_act])
    col0_1_mix = keras.layers.Add()([col0_0_act])
    col1_0_fc = keras.layers.Dense(units=64, use_bias=True)(col1_0_mix)
    col2_0_fc = keras.layers.Dense(units=64, use_bias=True)(col2_0_mix)
    col0_1_fc = keras.layers.Dense(units=64, use_bias=True)(col0_1_mix)
    col1_0_norm = keras.layers.LayerNormalization(epsilon=1e-05, scale=True)(col1_0_fc)
    col2_0_norm = keras.layers.LayerNormalization(epsilon=1e-05, scale=True)(col2_0_fc)
    col0_1_norm = keras.layers.LayerNormalization(epsilon=1e-05, scale=True)(col0_1_fc)
    col1_0_act = keras.activations.gelu(col1_0_norm, approximate=False)
    col2_0_act = keras.activations.gelu(col2_0_norm, approximate=False)
    col0_1_act = keras.activations.gelu(col0_1_norm, approximate=False)
    col3_0_mix = keras.layers.Add()([col1_0_act, col2_0_act])
    col1_1_mix = keras.layers.Add()([col1_0_act, col0_1_act])
    col2_1_mix = keras.layers.Add()([col2_0_act, col0_1_act])
    col0_2_mix = keras.layers.Add()([col0_1_act])
    col3_0_fc = keras.layers.Dense(units=64, use_bias=True)(col3_0_mix)
    col1_1_fc = keras.layers.Dense(units=64, use_bias=True)(col1_1_mix)
    col2_1_fc = keras.layers.Dense(units=64, use_bias=True)(col2_1_mix)
    col0_2_fc = keras.layers.Dense(units=64, use_bias=True)(col0_2_mix)
    col3_0_norm = keras.layers.LayerNormalization(epsilon=1e-05, scale=True)(col3_0_fc)
    col1_1_norm = keras.layers.LayerNormalization(epsilon=1e-05, scale=True)(col1_1_fc)
    col2_1_norm = keras.layers.LayerNormalization(epsilon=1e-05, scale=True)(col2_1_fc)
    col0_2_norm = keras.layers.LayerNormalization(epsilon=1e-05, scale=True)(col0_2_fc)
    col3_0_act = keras.activations.gelu(col3_0_norm, approximate=False)
    col1_1_act = keras.activations.gelu(col1_1_norm, approximate=False)
    col2_1_act = keras.activations.gelu(col2_1_norm, approximate=False)
    col0_2_act = keras.activations.gelu(col0_2_norm, approximate=False)
    col3_1_mix = keras.layers.Add()([col3_0_act, col1_1_act, col2_1_act])
    col1_2_mix = keras.layers.Add()([col1_1_act, col0_2_act])
    col2_2_mix = keras.layers.Add()([col2_1_act, col0_2_act])
    col0_3_mix = keras.layers.Add()([col0_2_act])
    col3_1_fc = keras.layers.Dense(units=64, use_bias=True)(col3_1_mix)
    col1_2_fc = keras.layers.Dense(units=64, use_bias=True)(col1_2_mix)
    col2_2_fc = keras.layers.Dense(units=64, use_bias=True)(col2_2_mix)
    col0_3_fc = keras.layers.Dense(units=64, use_bias=True)(col0_3_mix)
    col3_1_norm = keras.layers.LayerNormalization(epsilon=1e-05, scale=True)(col3_1_fc)
    col1_2_norm = keras.layers.LayerNormalization(epsilon=1e-05, scale=True)(col1_2_fc)
    col2_2_norm = keras.layers.LayerNormalization(epsilon=1e-05, scale=True)(col2_2_fc)
    col0_3_norm = keras.layers.LayerNormalization(epsilon=1e-05, scale=True)(col0_3_fc)
    col3_1_act = keras.activations.gelu(col3_1_norm, approximate=False)
    col1_2_act = keras.activations.gelu(col1_2_norm, approximate=False)
    col2_2_act = keras.activations.gelu(col2_2_norm, approximate=False)
    col0_3_act = keras.activations.gelu(col0_3_norm, approximate=False)
    col3_2_mix = keras.layers.Add()([col3_1_act, col1_2_act, col2_2_act])
    col1_3_mix = keras.layers.Add()([col1_2_act, col0_3_act])
    col2_3_mix = keras.layers.Add()([col2_2_act, col0_3_act])
    col3_2_fc = keras.layers.Dense(units=64, use_bias=True)(col3_2_mix)
    col1_3_fc = keras.layers.Dense(units=64, use_bias=True)(col1_3_mix)
    col2_3_fc = keras.layers.Dense(units=64, use_bias=True)(col2_3_mix)
    col3_2_norm = keras.layers.LayerNormalization(epsilon=1e-05, scale=True)(col3_2_fc)
    col1_3_norm = keras.layers.LayerNormalization(epsilon=1e-05, scale=True)(col1_3_fc)
    col2_3_norm = keras.layers.LayerNormalization(epsilon=1e-05, scale=True)(col2_3_fc)
    col3_2_act = keras.activations.gelu(col3_2_norm, approximate=False)
    col1_3_act = keras.activations.gelu(col1_3_norm, approximate=False)
    col2_3_act = keras.activations.gelu(col2_3_norm, approximate=False)
    col3_3_mix = keras.layers.Add()([col3_2_act, col1_3_act, col2_3_act])
    col3_3_fc = keras.layers.Dense(units=64, use_bias=True)(col3_3_mix)
    col3_3_norm = keras.layers.LayerNormalization(epsilon=1e-05, scale=True)(col3_3_fc)
    col3_3_act = keras.activations.gelu(col3_3_norm, approximate=False)
    return keras.Model(inputs=x, outputs=col3_3_act, name="lattice_3d")
